// TH14 v1.00b Extra 道中波 th14_s7_w05
// 源：st07.ecl.txt MainSub04 798-812（A组 8 对 GirlC01，16 个 F 计划创建）。
// 依赖：GirlC01 343-365、GirlC01_at 367-398。入口 $I0=2/%F2=-π/2 在本闭包内不被读取；
// MainSub04 813 起的 B/C/D 组只是 context_only，不执行。
// 源 enmCreateF 的 F 门（boss0 可找到则跳过创建）按已批准奖励波独立训练口径处理：
// 本卡不创建 boss0，因此每个计划事件都实际编队，不带上游 Boss 或其残敌/尾弹。

const TIME_LIMIT: int = 3024;
const OPENING_BUFFER: int = 120;

// GirlC01_at（367-398）：180 轮 × 5 发，每轮末 wait(2)。
// etNew/etAim(3)/etSprite(5,2)/etCount(1,1)/etAngle(0,30°)/etSpeed(1.5,1.0)
// → aim3 在 N=1/M=1 时角即 alpha，速即 s0=1.5；弹型 type5→TH14_BALL2，color2。
// EX 只有 ANIM(a=1)/BRIGHT(a=1)/SPEEDUP：出生动画、混合与 SPEEDUP 无剩余物理行为；
// ANIM 进入时的 position -= 4*velocity 属已批准的保留退位移，1.5*4=6px 沿弹角反向。
async sub girlc01_at() {
    var c: angle = (rand(65536) as angle);              // %C = %RANDRAD
    var round: int = 0;
    while round < 180 {                                  // $D = 180
        var r1: fx = (rand(65536) as fx) / 1024fx;       // circlePos(..., %RANDF*64) → [0,64)
        var ox: fx = $self_x + r1 * cos(c);              // %A + %FINAL_X（本帧位置快照）
        var oy: fx = $self_y + r1 * sin(c);              // %B + %FINAL_Y
        var shot: angle = (rand(65536) as angle);        // etAngle(0, %RANDRAD, 0)
        var e: int = 0;
        while e < 5 {                                    // $E = 5
            var oa: angle = (rand(65536) as angle);      // etOffsetRad(0, %RANDRAD, ...)
            var orad: fx = (rand(65536) as fx) / 8192fx; // %RANDF*8 → [0,8)
            var bx: fx = ox + orad * cos(oa) - 6fx * cos(shot);
            var by: fx = oy + orad * sin(oa) - 6fx * sin(shot);
            _ = fire(TH14_BALL2, 2, bx, by, 1.5fx, shot, none, none); // etOn(0)
            e = e + 1;
        }
        c = c + ((8192 + rand(16384)) as angle);         // %C += π/4 + π/2*%RANDF
        wait(2);
        round = round + 1;
    }
}

// GirlC01（343-365）：真实敌本体。anm 选档、普通掉落按共用取舍省略；
// 框按源第一值×0.5（setHurtbox(24,24)→12、setHitbox(16,16)→8）。
async sub girlc01() {
    set_invuln(65535);
    set_hurtbox(12fx);
    set_hitbox(8fx);
    move_vel(0, 90deg, 1.5fx, EASE_LINEAR);              // moveVel(π/2, 1.5)
    move_vel(80, aim_player(), 0.1fx, EASE_QUAD_IN);     // moveVelTime(80,1,ANGLE_PLAYER,0.1)
    wait(60);
    spawn girlc01_at();                                  // @GirlC01_at() async
    wait(200);
    move_vel(80, 90deg, 1.0fx, EASE_QUAD_IN);            // moveVelTime(80,1,π/2,1.0)
    loop { wait(1000); }                                 // GirlC01_424→404: wait(1000) 循环
}

// MainSub04（798-812）：wait(200)，随后 8 对：左 200+200k、右 300+200k。
// 每个 F 计划事件按 boss0 不在场的独立编队执行；原 wait 与左右顺序保留。
async sub formation() {
    wait(OPENING_BUFFER);                                // 卡帧 0 起的开场缓冲
    wait(200);                                           // 798-805 的 wait(200)
    var k: int = 0;
    while k < 8 {                                        // $A = 8
        _ = spawn_enemy(-90fx, -32fx, 360, 0, 1000, 0, girlc01); // enmCreateF 左
        wait(100);
        _ = spawn_enemy(90fx, -32fx, 360, 0, 1000, 0, girlc01);  // enmCreateF 右
        wait(100);
        k = k + 1;
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, formation, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

